function findDealerEmail(codigoDealer) {
    const codigoStr = String(codigoDealer || '').trim();
    for (const [email, codigos] of Object.entries(DEALER_ASSIGNMENTS)) {
        if (codigos.includes(codigoStr)) return email;
    }
    return null;
}

function normalizeField(value) {
    const v = String(value || '').trim().toLowerCase();
    return FIELD_ALIASES[v] ?? v;
}

function findPilotCode(origen, suborigen, detalle, subdetalle) {
    const o  = normalizeField(origen);
    const s  = normalizeField(suborigen);
    const d  = normalizeField(detalle);
    const sd = normalizeField(subdetalle);

    // 1° intento: match exacto con los 4 campos (case-insensitive)
    const exactMatch = ORIGEN_PILOT_MAP.find(item =>
        normalizeField(item.origen)     === o  &&
        normalizeField(item.suborigen)  === s  &&
        normalizeField(item.detalle)    === d  &&
        normalizeField(item.subdetalle) === sd
    );
    if (exactMatch) return exactMatch.pilotCode;

    // 2° intento: match por origen, suborigen y subdetalle (ignorando detalle)
    if (sd) {
        const fallbackMatch = ORIGEN_PILOT_MAP.find(item =>
            normalizeField(item.origen)     === o  &&
            normalizeField(item.suborigen)  === s  &&
            normalizeField(item.subdetalle) === sd
        );
        if (fallbackMatch) return fallbackMatch.pilotCode;
    }

    // 3° intento: match por origen, suborigen y detalle (ignorando subdetalle)
    if (d) {
        const detalleMatch = ORIGEN_PILOT_MAP.find(item =>
            normalizeField(item.origen)    === o &&
            normalizeField(item.suborigen) === s &&
            normalizeField(item.detalle)   === d
        );
        if (detalleMatch) return detalleMatch.pilotCode;
    }

    // 4° intento: match solo por origen + suborigen (cuando detalle y subdetalle vienen vacíos)
    const subOrigenMatch = ORIGEN_PILOT_MAP.find(item =>
        normalizeField(item.origen)    === o &&
        normalizeField(item.suborigen) === s
    );
    if (subOrigenMatch) return subOrigenMatch.pilotCode;

    // 5° intento: default
    return 'leads_nissan';
}

function getBusinessTypeId(tipoRegistro) {
    const t = String(tipoRegistro || '').trim();
    if (t === 'ARG Vehículos Nuevos') return 1;
    if (t === 'ARG Saving Plan' || t === 'ARG Savings Plan' || t === 'ARG Plan de Ahorro' ) return 3;
    return 1;
}

function normalizePhone(raw) {
    const telefono = String(raw || '');
    let telefonoLimpio = telefono.replace(/\D/g, '');

    if (telefonoLimpio.startsWith('549')) {
        // Ya viene bien formado, no tocar
    } else if (telefonoLimpio.startsWith('54')) {
        // Tiene código de país pero le falta el 9 del celular -> se lo insertamos
        telefonoLimpio = '549' + telefonoLimpio.slice(2);
    } else if (telefonoLimpio.startsWith('55')) {
        // Brasil u otro caso ya con código de país, se deja como está
    } else if (telefonoLimpio.length >= 8) {
        telefonoLimpio = '549' + telefonoLimpio;
    }

    return telefonoLimpio || telefono.trim();
}

const lead = $input.first().json;

