// Campo dealer: nuevo formato usa "ID de la concesionaria de Interés", fallback al viejo "ID DEALER"
const dealerId = lead['ID de la concesionaria de Interés'] || lead['ID DEALER'] || '';

// Campo LeadId: sigue siendo "LeadId" en ambos formatos
const leadId = lead['LeadId'] || '';

return {
    ...lead,
    TELEFONO_NORMALIZADO: telefono,
    DEALER_ID: String(dealerId).trim(),
    LEAD_ID: String(leadId).trim(),
    dealerEmail: findDealerEmail(dealerId),
    pilotCode: findPilotCode(
        lead['Origen del lead'],
        lead['Sub Origen'],
        lead['Detalle del lead'],
        lead['Sub Detalle']
